/**
 * @param queryVector the query's embedding when the caller already computed it (the answer cache
 * does), so the question is not embedded twice; null to embed here
 */
@Transactional(readOnly = true)
public List<SearchHit> search(Repo repo, String query, float[] queryVector, int limit, Mode mode) {
	if (repo.activeJobId() == null) {
		throw new NotIndexedException(repo);
	}
	if (query == null || query.isBlank()) {
		throw new IllegalArgumentException("Query must not be blank");
	}
	Timer.Sample sample = Timer.start(meters);
	try {
		int candidates = limit * CANDIDATE_FACTOR;
		List<Long> vector = mode == Mode.KEYWORD ? List.of()
				: vectorRanking(repo.activeJobId(), queryVector != null ? queryVector : embeddings.embedQuery(query),
						candidates);
		List<Long> keyword = mode == Mode.VECTOR ? List.of() : keywordRanking(repo.activeJobId(), query, candidates);

		List<Map.Entry<Long, Double>> fused = ReciprocalRankFusion
			.fuse(List.of(vector, keyword), ReciprocalRankFusion.DEFAULT_K)
			.stream()
			.limit(limit)
			.toList();
		return hydrate(fused, vector, keyword);
	}
	finally {
		sample.stop(meters.timer("repomind.search.latency", "mode", mode.name().toLowerCase()));
	}
}

/** @return ids ordered by fused score, best first; ties keep first-seen order */
public static <T> List<Map.Entry<T, Double>> fuse(List<List<T>> rankings, int k) {
	Map<T, Double> scores = new LinkedHashMap<>();
	for (List<T> ranking : rankings) {
		for (int i = 0; i < ranking.size(); i++) {
			scores.merge(ranking.get(i), 1.0 / (k + i + 1), Double::sum);
		}
	}
	return scores.entrySet()
		.stream()
		.sorted(Map.Entry.<T, Double>comparingByValue(Comparator.reverseOrder()))
		.toList();
}

static Result run(HybridSearch search, Repo repo, EvalSet eval) {
	Map<Mode, RetrievalScore> scores = new EnumMap<>(Mode.class);
	Map<Mode, List<String>> misses = new EnumMap<>(Mode.class);
	for (Mode mode : Mode.values()) {
		List<Outcome> outcomes = new ArrayList<>();
		List<String> missed = new ArrayList<>();
		for (Question q : eval.questions()) {
			List<SearchHit> hits = search.search(repo, q.question(), TOP_K, mode);
			int rank = q.firstRelevantRank(hits);
			outcomes.add(new Outcome(q.id(), q.category(), rank));
			if (rank == 0 || rank > 5) {
				missed.add(miss(q, rank, hits));
			}
		}
		scores.put(mode, RetrievalScore.of(outcomes));
		misses.put(mode, missed);
	}
	return new Result(scores, misses);
}

package dev.repomind.limits;

/**
 * Token-bucket rate limiting in Redis. The whole read-refill-take step runs as one Lua script, so
 * concurrent requests (from several app instances, too) cannot both spend the last token, and the
 * clock is Redis's own, so instances with skewed clocks agree.
 */
@Component
public class RateLimiter {

    private static final Logger log = LoggerFactory.getLogger(RateLimiter.class);

    /**
     * KEYS[1] bucket; ARGV[1] capacity; ARGV[2] refill per millisecond.
     * Returns {allowed (1/0), tokens left, milliseconds until a token is available}.
     */
    private static final RedisScript<List> TOKEN_BUCKET = new DefaultRedisScript<>("""
        local capacity = tonumber(ARGV[1])
        local refill = tonumber(ARGV[2])
        local time = redis.call('TIME')
        local now = tonumber(time[1]) * 1000 + math.floor(tonumber(time[2]) / 1000)
        local state = redis.call('HMGET', KEYS[1], 'tokens', 'ts')
        local tokens = tonumber(state[1]) or capacity
        local ts = tonumber(state[2]) or now
        tokens = math.min(capacity, tokens + math.max(0, now - ts) * refill)
        local allowed, wait = 0, 0
        if tokens >= 1 then
          tokens = tokens - 1
          allowed = 1
        else
          wait = math.ceil((1 - tokens) / refill)
        end
        redis.call('HSET', KEYS[1], 'tokens', tostring(tokens), 'ts', tostring(now))
        redis.call('PEXPIRE', KEYS[1], math.ceil(capacity / refill) + 1000)
        return {allowed, math.floor(tokens), wait}
        """, List.class);

    private final StringRedisTemplate redis;

    private final MeterRegistry meters;

    public RateLimiter(StringRedisTemplate redis, MeterRegistry meters) {
    }

    /**
     * Takes one request from the client's bucket. Fails open if Redis is unavailable.
     */
    public Decision acquire(ApiClient client);
}

/** Takes one request from the client's bucket. Fails open if Redis is unavailable. */
public Decision acquire(ApiClient client) {
	int perMinute = client.policy().requestsPerMinute();
	try {
		List<?> result = redis.execute(TOKEN_BUCKET, List.of("repomind:rate:" + client.id()),
				String.valueOf(perMinute), String.valueOf(perMinute / 60_000.0));
		boolean allowed = ((Number) result.get(0)).longValue() == 1;
		long remaining = ((Number) result.get(1)).longValue();
		long waitMs = ((Number) result.get(2)).longValue();
		if (!allowed) {
			meters.counter("repomind.limits.rejected", "reason", "rate").increment();
		}
		return new Decision(allowed, perMinute, remaining, allowed ? 0 : Math.max(1, (waitMs + 999) / 1000));
	}
	catch (RuntimeException ex) {
		// availability over strictness: an outage of the limiter must not take the API down
		meters.counter("repomind.limits.errors", "operation", "rate").increment();
		log.warn("Rate limiter unavailable, allowing request from {}: {}", client.id(), ex.getMessage());
		return new Decision(true, perMinute, -1, 0);
	}
}

@Test
void rateLimitRejectsTheRequestAfterTheBurstWithRetryAfter() {
	for (int i = 0; i < 3; i++) {
		assertThat(get("/api/repos", "rate-test-key")).hasStatusOk()
			.headers()
			.hasValue("X-RateLimit-Limit", "3")
			.hasValue("X-RateLimit-Remaining", String.valueOf(2 - i));
	}

	MvcTestResult rejected = get("/api/repos", "rate-test-key");

	assertThat(rejected).hasStatus(HttpStatus.TOO_MANY_REQUESTS).headers().containsHeader("Retry-After");
	assertThat(Long.parseLong(rejected.getResponse().getHeader("Retry-After"))).isBetween(1L, 20L);
	assertThat(rejected).bodyJson().extractingPath("$.limit").isEqualTo("rate-limit");
	// other callers have their own buckets
	assertThat(get("/api/repos", null)).hasStatusOk();
}

package dev.repomind.limits;

/**
 * Model tokens per client per UTC day, counted in Redis. The budget is checked before a model call
 * and charged after it with the real usage, so one call can overshoot the budget by its own size;
 * that keeps the check to a single read instead of estimating a call's cost up front.
 */
@Component
public class TokenBudget {

    private static final Logger log = LoggerFactory.getLogger(TokenBudget.class);

    private final StringRedisTemplate redis;

    private final MeterRegistry meters;

    private final Clock clock;

    @Autowired
    public TokenBudget(StringRedisTemplate redis, MeterRegistry meters) {
    }

    TokenBudget(StringRedisTemplate redis, MeterRegistry meters, Clock clock) {
    }

    /**
     * Tokens left today (negative once a call has overshot), or empty when unknown because Redis is
     * unavailable.
     */
    public OptionalLong remaining(ApiClient client);

    /**
     * The guard to hand to model-calling code for this client.
     */
    public ModelBudget forClient(ApiClient client);

    long secondsUntilReset();

    private String key(ApiClient client);
}

