/**
 * @param failureRateThreshold percentage of failed calls in the window that opens the circuit
 * @param slidingWindowSize calls the failure rate is computed over
 * @param minimumCalls calls needed before the failure rate is evaluated
 * @param openFor how long an open circuit skips the provider before letting a probe call through
 * @param halfOpenCalls probe calls allowed while half-open
 */
public record CircuitBreaker(@DefaultValue("50") float failureRateThreshold, @DefaultValue("10") int slidingWindowSize, @DefaultValue("4") int minimumCalls, @DefaultValue("30s") Duration openFor, @DefaultValue("1") int halfOpenCalls) {
}

public RateLimitedException(RateLimiter.Decision decision) {
	super("Rate limit of " + decision.limit() + " requests per minute exceeded; retry in "
			+ decision.retryAfterSeconds() + "s");
	this.decision = decision;
}

@ExceptionHandler(RateLimitedException.class)
ResponseEntity<ProblemDetail> rateLimited(RateLimitedException ex) {
	return tooManyRequests(ex.getMessage(), ex.decision().retryAfterSeconds(), "rate-limit");
}

