/**
 * Verifies GitHub's {@code X-Hub-Signature-256} header: {@code sha256=} followed by the hex
 * HMAC-SHA256 of the raw request body, keyed with the webhook secret.
 */
public final class WebhookSignature {

    private static final String PREFIX = "sha256=";

    private WebhookSignature() {
    }

    public static String sign(String secret, byte[] payload);

    /**
     * Constant-time comparison, so response timing reveals nothing about the expected signature.
     */
    public static boolean isValid(String secret, byte[] payload, String header);
}

package dev.repomind.api;

/**
 * Receives GitHub webhooks; configure it with content type {@code application/json} and a secret.
 */
@RestController
public class GitHubWebhookController {

    private final WebhookHandler handler;

    public GitHubWebhookController(WebhookHandler handler) {
    }

    /**
     * The raw body is read as bytes because the signature covers the exact bytes GitHub sent.
     */
    @PostMapping("/api/github/webhook")
    ResponseEntity<WebhookHandler.Outcome> receive(@RequestHeader("X-GitHub-Event") String event, @RequestHeader(value = "X-Hub-Signature-256", required = false) String signature, @RequestBody byte[] payload);
}

@Test
void rejectsMissingWrongOrTamperedSignatures() {
	String secret = "It's a Secret to Everybody";
	String valid = WebhookSignature.sign(secret, PAYLOAD);

	assertThat(WebhookSignature.isValid(secret, PAYLOAD, valid)).isTrue();
	assertThat(WebhookSignature.isValid(secret, PAYLOAD, null)).isFalse();
