void shouldAllowSamePetNameForDifferentOwners() {
	Collection<PetType> types = this.types.findPetTypes();
	PetType catType = EntityUtils.getById(types, PetType.class, 1);

	Optional<Owner> owner1Opt = this.owners.findById(1);
